import {BEDROOMS,STATUSES,finite,materialize,rank,csv} from './analysis.js';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>finite(v)?v.toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2}):'Unavailable';
const num=v=>finite(v)?v.toLocaleString('en-US',{maximumFractionDigits:0}):'—';
const signedRange=values=>{const good=values.filter(finite),lo=Math.min(0,...good),hi=Math.max(0,...good),pad=Math.max((hi-lo)*.22,1);return [lo-pad,hi+pad];};
const pct=v=>finite(v)?`${v>0?'+':''}${v.toFixed(1)}%`:'Unavailable',share=v=>finite(v)?`${(100*v).toFixed(1)}%`:'Unavailable';
const shortBed=b=>b.replace(' bedroom',' BR').replace('6+ BRs','6+ BR');
const segment=r=>`${r.neighbourhood} · ${r.room_type.replace('Entire home/apt','Entire home')} · ${shortBed(r.bedroom_segment)}`;
const C={local:'#167d77',peer:'#7094b5',amber:'#bc793a',gray:'#e4ebe4',ink:'#264b3e',muted:'#8a9b8e',purple:'#9a84b4'};
const statusColor={'Persistent premium':C.amber,'Persistent discount':C.local,'Reversed':C.purple,'Neutral':'#92a392','Insufficient evidence':'#d6dfd4'};
const defaults={snapshot:'june',neighborhood:'Hollywood',room:'Entire home/apt',bedroom:'1 bedroom',stay:'0',source:'0',minimum:20,coverage:80,direction:'Both',top:10,tab:'detail'};
let state={...defaults},catalog,bundle,rows=[],ranked=[],current,requestId=0;
const cache=new Map();
const metric=(label,value,small='',highlight=false)=>`<div class="metric${highlight?' highlight':''}"><span class="label">${label}</span><strong>${value}</strong><small>${small}</small></div>`;
const panel=(id,title,desc,note='',full=false)=>`<article class="panel${full?' full':''}"><h3>${title}</h3><p class="desc">${desc}</p><div class="chart" id="${id}"></div>${note?`<p class="panel-note">${note}</p>`:''}</article>`;
function chart(id,traces,layout={},click){
  const base={height:310,autosize:true,paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{family:'DM Sans, Arial, sans-serif',size:11,color:'#7c9180'},margin:{l:47,r:25,t:33,b:48},legend:{orientation:'h',y:1.17,x:0,font:{size:10}},xaxis:{showgrid:false,zeroline:false,automargin:true},yaxis:{gridcolor:'#edf1eb',zeroline:false,automargin:true},hoverlabel:{bgcolor:'white',font:{color:C.ink}},...layout};
  base.xaxis={showgrid:false,zeroline:false,automargin:true,...layout.xaxis};base.yaxis={gridcolor:'#edf1eb',zeroline:false,automargin:true,...layout.yaxis};
  const graph=$(id);if(!graph)return;
  Plotly.newPlot(graph,traces,base,{responsive:true,displaylogo:false,modeBarButtonsToRemove:['select2d','lasso2d'],toImageButtonOptions:{format:'png',scale:2}}).then(()=>{if(click)graph.on('plotly_click',click);});
}
function unavailable(id,message){chart(id,[],{xaxis:{visible:false},yaxis:{visible:false},annotations:[{text:message,x:.5,y:.5,xref:'paper',yref:'paper',showarrow:false,font:{size:12,color:C.muted}}]});}
function options(id,values,labels=values){$(id).innerHTML=values.map((v,i)=>`<option value="${esc(v)}">${esc(labels[i])}</option>`).join('');}
function choose(r){state.neighborhood=r.neighbourhood;state.room=r.room_type;state.bedroom=r.bedroom_segment;sync();render();}
function sync(){for(const key of ['snapshot','neighborhood','room','bedroom','stay','source','minimum','coverage'])$(key).value=state[key];$('coverage-value').textContent=state.coverage+'%';}
function exportFile(records,name){const content=csv(records,records.length?undefined:['rank',...bundle.columns,'canonical_fingerprint']);const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function quality(r,period){
  if(!r)return '';
  let notes=r.warnings.split(' | ').filter(x=>!x.startsWith('No row-specific'));
  if(period){const other=period==='march'?'June':'March';notes=notes.filter(x=>!x.startsWith(other)&&!x.includes('deteriorated'));}
  const coverage=notes.filter(x=>x.includes('price coverage')),minimum=notes.filter(x=>x.includes('minimum evidence')||x.includes('segment absent')),bed=notes.some(x=>/bedroom|Studio/.test(x));
  return `${minimum.length?`<div class="notice"><strong>Evidence limit.</strong> ${minimum.map(esc).join(' ')}</div>`:''}${coverage.length?`<div class="notice"><strong>Price coverage needs attention.</strong> ${coverage.map(esc).join(' ')}</div>`:''}${bed?'<div class="notice"><strong>Bedroom composition changed.</strong> Unknown-bedroom exclusions or Studio coding changes can affect the comparison. Inspect the bedroom completeness chart and notes below.</div>':''}${notes.length?`<details><summary>Quality notes · ${notes.length} checks to consider</summary><ul>${notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:'<p class="quiet">No row-specific quality warning at the current settings.</p>'}`;
}
function method(){return `<details><summary>Data quality & methodology</summary><p><strong>Source:</strong> supplied Inside Airbnb Los Angeles detailed-listings snapshots, 16 March and 15 June 2026. These are repeated cross-sections, not matched-listing or causal price changes.</p><p><strong>Peers include the selected neighborhood.</strong> LA listing prices are pooled under identical room, bedroom, stay and source filters. Unknown dimensions remain in canonical data but are excluded from comparable groups. Missing-price rows still contribute to coverage and valid context.</p><p><strong>Price evidence:</strong> median and linear-interpolated P25/P75. No imputation, outlier cap or removal. The full price range is retained. Both local and peer priced counts must meet the adjustable minimum. The fixed small-sample flag remains &lt;20. Coverage warnings do not exclude records.</p><p><strong>Priority:</strong> only same-sign, nonzero premiums/discounts in both dates rank. Score = smaller absolute March/June premium, in percentage points. Context is never scored. These are exploratory thresholds, not significance tests.</p><p><strong>Composition:</strong> zero bedrooms = Studio; missing bedrooms = Unknown; ≥6 = 6+. Unknown-bedroom warnings use ≥25% or ≥10 percentage-point deterioration. Their proposed status and source-coding limits remain disclosed. Review score zero is retained and flagged.</p><div class="table-wrap"><table><thead><tr><th>Nominal date</th><th>Rows</th><th>Missing prices</th><th>Unknown bedrooms</th><th>Recorded Studio zeros</th><th>Actual scrape dates</th></tr></thead><tbody>${catalog.quality.map(q=>`<tr><td>${q.snapshot_date}</td><td>${num(q.clean_rows)}</td><td>${num(q.missing_price_rows)}</td><td>${num(q.unknown_bedroom_rows)}</td><td>${num(q.zero_bedroom_rows)}</td><td>${q.actual_scrape_dates.join(', ')}</td></tr>`).join('')}</tbody></table></div><p>Canonical fingerprint: ${catalog.fingerprint}</p><p>Advertised prices do not establish optimal prices, revenue, demand, occupancy or causal effects. Actual scrape dates and previous-scrape source categories may differ from nominal extract dates.</p></details>`;}
function evidenceTable(r){return `<details><summary>Supporting numbers · full evidence</summary><div class="table-wrap"><table><thead><tr><th>Evidence field</th><th>Value</th></tr></thead><tbody>${Object.entries(r).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v===null?'Unavailable':esc(v)}</td></tr>`).join('')}</tbody></table></div></details>`;}
function band(r,d,id){
  const traces=[];
  for(const [prefix,name,color,y] of [['','This segment',C.local,1],['peer_','LA peer',C.peer,0]]){
    const med=r[prefix+'median_price_usd_'+d],q1=r[prefix+'p25_price_usd_'+d],q3=r[prefix+'p75_price_usd_'+d];
    if(!finite(med))continue;
    if(finite(q1)&&finite(q3))traces.push({x:[q1,q3],y:[y,y],mode:'lines',line:{color,width:16},opacity:.22,showlegend:false,hoverinfo:'skip'});
    traces.push({x:[med],y:[y],mode:'markers+text',text:[money(med)],textposition:'top center',textfont:{size:14,color:C.ink},marker:{color,size:12,symbol:'diamond'},name,customdata:[[q1,q3,r[prefix+'priced_rows_'+d]]],hovertemplate:'Median $%{x:,.2f}<br>P25 $%{customdata[0]:,.2f} · P75 $%{customdata[1]:,.2f}<br>%{customdata[2]:,} valid prices<extra>'+name+'</extra>'});
  }
  traces.length?chart(id,traces,{showlegend:false,xaxis:{tickprefix:'$',title:{text:'Advertised price (USD)',font:{size:10}}},yaxis:{tickvals:[0,1],ticktext:['LA peer','This segment'],range:[-.55,1.65],showgrid:false}}):unavailable(id,'No valid positive prices.');
}
function histogram(r,d,id){const date=d==='march'?'2026-03-16':'2026-06-15',key=[date,r.neighbourhood,r.room_type,r.bedroom_segment].join('|'),b=bundle.histograms[key];if(!b){unavailable(id,'No valid positive prices.');return;}
  const [lo,hi,counts]=b,step=(hi-lo)/counts.length,x=counts.map((_,i)=>lo+(i+.5)*step);
  chart(id,[{type:'bar',x,y:counts,width:counts.map(()=>step*.92),marker:{color:C.local,opacity:.86},hovertemplate:'Price bin center $%{x:,.2f}<br>%{y:,} listings<extra></extra>'}],{xaxis:{tickprefix:'$',title:'Advertised price (USD)'},yaxis:{title:'Listings'},shapes:[{type:'line',x0:r['median_price_usd_'+d],x1:r['median_price_usd_'+d],y0:0,y1:1,yref:'paper',line:{color:C.amber,width:1.5,dash:'dash'}}],annotations:[{x:r['median_price_usd_'+d],y:1.06,yref:'paper',text:'Median '+money(r['median_price_usd_'+d]),showarrow:false,font:{size:10,color:C.amber}}]});
}
function coverage(r,period,id){const ds=period?[period]:['march','june'],labels=[],priced=[],missing=[],custom=[];
  for(const d of ds)for(const [p,name] of [['','Local'],['peer_','Peer']]){const share=r[p+'price_coverage_'+d],total=r[p+'listing_rows_'+d],valid=r[p+'priced_rows_'+d];if(!finite(share)||!total)continue;labels.push(`${d==='march'?'March':'June'} · ${name}`);priced.push(100*share);missing.push(100*(1-share));custom.push([valid,total,total-valid]);}
  if(!labels.length){unavailable(id,'No comparable listings.');return;}
  chart(id,[{type:'bar',orientation:'h',y:labels,x:priced,name:'Valid price',marker:{color:C.local},text:priced.map(x=>x.toFixed(1)+'%'),textposition:'inside',insidetextfont:{color:'white'},customdata:custom,hovertemplate:'%{y}: %{x:.1f}%<br>%{customdata[0]:,} priced / %{customdata[1]:,} listings<extra></extra>'},{type:'bar',orientation:'h',y:labels,x:missing,name:'Price unavailable',marker:{color:C.gray},customdata:custom,hovertemplate:'%{customdata[2]:,} listings without a valid price<extra></extra>'}],{height:period?240:310,barmode:'stack',bargap:.45,xaxis:{range:[0,100],ticksuffix:'%'},yaxis:{autorange:'reversed',showgrid:false},shapes:[{type:'line',x0:state.coverage,x1:state.coverage,y0:0,y1:1,yref:'paper',line:{color:C.amber,dash:'dash',width:1.5}}],annotations:[{x:state.coverage,y:-.3,yref:'paper',text:`${state.coverage}% warning threshold`,showarrow:false,font:{size:9,color:C.amber}}]});
}
const contextMetrics=[['availability_90','Available days · next 90 days','days'],['reviews_ltm','Reviews · last 12 months','reviews'],['value_score','Review value · 0–5','score'],['minimum_nights','Minimum stay requirement','nights']];
function contextPanels(prefix){return `<div class="grid">${contextMetrics.map(([key,title,unit])=>panel(prefix+key,title,'Median · this segment vs LA peer',`Independent ${unit} scale; hover for valid observation counts.`)).join('')}</div>`;}
function contextPlots(r,period,prefix){for(const [key,,unit] of contextMetrics){const ds=period?[period]:['march','june'],traces=[];for(const [p,name,color] of [['','This segment',C.local],['peer_','LA peer',C.peer]])traces.push({type:'bar',x:ds.map(d=>d==='march'?'March':'June'),y:ds.map(d=>r[p+key+'_median_'+d]),name,marker:{color},text:ds.map(d=>finite(r[p+key+'_median_'+d])?r[p+key+'_median_'+d].toFixed(2):''),textposition:'outside',cliponaxis:false,customdata:ds.map(d=>r[p+key+'_valid_n_'+d]),hovertemplate:'%{x}<br>Median %{y:,.2f} '+unit+'<br>Valid observations: %{customdata:,}<extra>'+name+'</extra>'});chart(prefix+key,traces,{height:265,barmode:'group',bargap:.5,yaxis:{title:unit,rangemode:'tozero',...(key==='value_score'?{range:[0,5.6]}:{})}});}}
function renderDetail(){const r=current,d=state.snapshot,$body=$('detail-body');
  if(!r||r['listing_rows_'+d]===null){$body.innerHTML='<div class="notice">No comparable listings for this segment and snapshot under these filters. Choose another segment or broaden the stay/source filters.</div>'+method();return;}
  const premium=r['premium_pct_'+d];
  $body.innerHTML=`<div class="section-intro"><h2>Your segment, at a glance</h2><p>${d==='june'?'15 June':'16 March'} 2026 · observed advertised prices</p></div><div class="metrics">${metric('Median advertised price',money(r['median_price_usd_'+d]),'USD per advertised night',true)}${metric('Relative to LA peer',pct(premium),'Same room & bedroom group')}${metric('Comparable listings',num(r['listing_rows_'+d]),num(r['priced_rows_'+d])+' with valid prices')}${metric('Price coverage',share(r['price_coverage_'+d]),'Of comparable listings')}${metric('Middle 50% spread',money(r['price_iqr_usd_'+d]),'P75 minus P25')}</div><div class="insight">${finite(premium)?`<strong>The local median is ${Math.abs(premium).toFixed(1)}% ${premium>0?'above':premium<0?'below':'equal to'} the LA peer median.</strong> Compare the price spread and the evidence before drawing a pricing conclusion.`:'<strong>Premium unavailable.</strong> Both local and peer priced counts must meet the current minimum.'}</div><div class="grid">${panel('detail-hist','Where do prices sit?','Distribution of all valid positive prices','20 equal-width bins over the full range (one if constant); no outlier clipping. Dashed line = median.')}${panel('detail-band','How does this compare?','Local vs inclusive LA peer','Diamond = median. Band = middle 50% (P25–P75), not a confidence interval.')}</div><div class="section-label">CONTEXT BEHIND THE PRICE</div>${contextPanels('detail-')}${panel('detail-coverage','How much evidence is available?','Valid prices vs missing or invalid prices','Coverage warnings do not remove listings; hover for the exact priced/listing denominators.',true)}${quality(r,d)}<div class="actions"><button class="action primary" id="detail-export">↓ Export this segment’s evidence</button><button class="action" id="see-comparison">Compare March & June →</button></div>${evidenceTable(r)}${method()}`;
  histogram(r,d,'detail-hist');band(r,d,'detail-band');contextPlots(r,d,'detail-');coverage(r,d,'detail-coverage');$('detail-export').onclick=()=>exportFile([r],'selected_segment_evidence.csv');$('see-comparison').onclick=()=>switchTab('comparison');
}
function renderComparison(){const r=current,$body=$('comparison-body');if(!r){$body.innerHTML='<div class="notice">No segment under these filters.</div>'+method();return;}
  $body.innerHTML=`<div class="section-intro"><h2>What changed between snapshots?</h2><p>The same segment and shared filters, viewed in March and June.</p></div><div class="metrics three">${metric('Median change',money(r.change_usd),'June minus March',true)}${metric('Change from March',pct(r.change_pct),'March median is the denominator')}${metric('Repeated price pattern',esc(r.persistence_status),'Evidence threshold applied')}</div><div class="insight"><strong>March ${money(r.median_price_usd_march)} → June ${money(r.median_price_usd_june)}.</strong> Price levels, evidence coverage and composition belong in the same conversation.</div><div class="grid">${panel('comp-price','Price levels and spread','Median advertised prices · local vs LA peer','Whiskers show P25–P75. Two repeated cross-sections, not a monthly time series or confidence interval.')}${panel('comp-premium','Did the relative price gap repeat?','Same-date LA peer = zero','Right of zero means premium; left means discount. Unavailable premiums are never plotted as zero.')}${panel('comp-coverage','Is price evidence comparable?','Priced share of known-dimension listings','Hover for listing counts. Dashed line = current coverage warning threshold.')}${panel('comp-bedroom','Did bedroom completeness change?','Unknown-bedroom share before bedroom exclusions','Missing bedrooms can change the comparable population. Studio and Unknown remain distinct.')}</div><details id="context-toggle"><summary>Explore how availability, reviews and stay context changed</summary>${contextPanels('comp-context-')}</details>${quality(r)}<div class="actions"><button class="action primary" id="comparison-export">↓ Export comparison evidence</button></div>${evidenceTable(r)}${method()}`;
  const traces=[];for(const [p,name,color] of [['','This segment',C.local],['peer_','LA peer',C.peer]]){const vals=['march','june'].map(d=>r[p+'median_price_usd_'+d]);traces.push({type:'scatter',mode:'lines+markers',x:['March','June'],y:vals,name,line:{color,width:2.5},marker:{color,size:9},connectgaps:false,error_y:{type:'data',symmetric:false,array:['march','june'].map((d,i)=>finite(vals[i])?r[p+'p75_price_usd_'+d]-vals[i]:null),arrayminus:['march','june'].map((d,i)=>finite(vals[i])?vals[i]-r[p+'p25_price_usd_'+d]:null),color,width:7,thickness:1.4},hovertemplate:'%{x}: $%{y:,.2f}<extra>'+name+'</extra>'});}chart('comp-price',traces,{yaxis:{tickprefix:'$',title:'Median advertised price (USD)'}});
  const premiums=[r.premium_pct_march,r.premium_pct_june];if(premiums.every(v=>!finite(v)))unavailable('comp-premium','Premium unavailable: minimum evidence not met.');else chart('comp-premium',[{type:'bar',orientation:'h',y:['March','June'],x:premiums,marker:{color:premiums.map(x=>x>0?C.amber:C.local)},text:premiums.map(pct),textposition:'outside',cliponaxis:false,hovertemplate:'%{y}: %{x:+.1f}%<extra></extra>'}],{xaxis:{range:signedRange(premiums),ticksuffix:'%',title:'Relative to same-date peer (%)',zeroline:true,zerolinecolor:'#a0b2a1'},yaxis:{autorange:'reversed',showgrid:false},showlegend:false});
  coverage(r,null,'comp-coverage');const b=[];for(const [p,name,color] of [['local','Local',C.local],['peer','LA peer',C.peer]])b.push({type:'bar',x:['March','June'],y:['march','june'].map(d=>finite(r[p+'_unknown_bedroom_share_'+d])?100*r[p+'_unknown_bedroom_share_'+d]:null),name,marker:{color},text:['march','june'].map(d=>share(r[p+'_unknown_bedroom_share_'+d])),textposition:'outside',cliponaxis:false,customdata:['march','june'].map(d=>r[p+'_bedroom_base_rows_'+d]),hovertemplate:'%{x}: %{y:.1f}% unknown<br>Pre-bedroom population: %{customdata:,}<extra>'+name+'</extra>'});chart('comp-bedroom',b,{barmode:'group',yaxis:{range:[0,110],ticksuffix:'%',title:'Unknown bedrooms'},shapes:[{type:'line',x0:0,x1:1,xref:'paper',y0:25,y1:25,line:{color:C.amber,dash:'dash',width:1}}]});
  $('context-toggle').ontoggle=()=>{if($('context-toggle').open)contextPlots(r,null,'comp-context-');};$('comparison-export').onclick=()=>exportFile([r],'selected_segment_evidence.csv');
}
function rowQualityLabel(r){
  const parts=r.warnings.split(' | ').filter(p=>!p.startsWith('No row-specific'));
  if(!parts.length)return 'No warning';
  const primary=parts.find(p=>p.includes('price coverage'))||parts.find(p=>/bedroom|Studio/.test(p))||parts[0];
  const label=primary.includes('price coverage')?primary.replace(' price coverage ',' coverage ').replace(' is below the ',' < ').replace(' warning threshold.',''):primary.includes('source caution')?'Source caution':primary.includes('bedroom')?'Bedroom composition caution':primary;
  return label+(parts.length>1?` · +${parts.length-1} notes`:'');
}
function renderShortlist(){const $body=$('shortlist-body');ranked=rank(rows,state.direction);const premium=ranked.filter(r=>r.direction==='Premium').length,discount=ranked.length-premium;
  $body.innerHTML=`<div class="section-intro"><h2>Start with a pattern worth reviewing</h2><p>All LA segments under your shared stay/source filters. Detail selectors do not limit this list.</p></div><div class="controls"><div class="segmented">${['Both','Premium','Discount'].map(d=>`<button class="${d===state.direction?'active':''}" data-direction="${d}">${d==='Both'?'All patterns':d+'s'}</button>`).join('')}</div><label>Show <select id="top" aria-label="Number of priorities shown"><option>5</option><option>10</option><option>15</option><option>20</option></select> priorities</label></div><div class="metrics three">${metric('Segments to review',num(ranked.length),'Qualifying in both snapshots',true)}${metric('Persistent premiums',num(premium),'Above the same-date peers')}${metric('Persistent discounts',num(discount),'Below the same-date peers')}</div>${ranked.length?panel('priority-bars','The largest repeated price gaps','Ranked by the smaller absolute March/June premium','Bars retain their signs; context is not part of the score. Click a bar to inspect that segment.',true):'<div class="notice">No persistent segments meet these settings. Broaden the filters or adjust the exploratory minimum.</div>'}<div class="grid">${panel('persistence','Did the pattern repeat?','One point = a segment with evidence in both dates','Upper right: persistent premium. Lower left: persistent discount. Opposite quadrants: reversed. Missing premiums are omitted. Click a point to inspect.')}${panel('patterns','How much of the market qualifies?','All shared filters · independent of direction above','Counts are segments, not listings. One-date groups can have insufficient evidence.')}</div>${ranked.length?`<div class="inspect"><label>Inspect a shortlisted segment<select id="inspect" aria-label="Inspect a shortlisted segment"><option value="">Choose a segment to see its evidence…</option>${ranked.map((r,i)=>`<option value="${i}">#${i+1} · ${esc(segment(r))}</option>`).join('')}</select></label></div>`:''}<div id="selected-review"></div><div class="actions"><button class="action primary" id="shortlist-export">↓ Export visible shortlist</button></div><details><summary>Browse all ${num(ranked.length)} shortlisted segments</summary><p>Click a row to inspect its evidence. Prices, counts, contexts, warnings and all settings are retained in the export.</p><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Segment</th><th>Pattern</th><th>Score (pp)</th><th>March coverage</th><th>June coverage</th><th>Notes</th></tr></thead><tbody>${ranked.map((r,i)=>`<tr data-segment="${i}"><td>${i+1}</td><td>${esc(segment(r))}</td><td><span class="badge ${r.direction==='Premium'?'premium':''}">${r.direction}</span></td><td class="num">${r.review_score.toFixed(1)}</td><td class="num">${share(r.price_coverage_march)}</td><td class="num">${share(r.price_coverage_june)}</td><td><span title="${esc(r.warnings)}">${esc(rowQualityLabel(r))}</span></td></tr>`).join('')}</tbody></table></div></details>${method()}`;
  $('top').value=state.top;$('top').onchange=e=>{state.top=+e.target.value;renderShortlist();};document.querySelectorAll('[data-direction]').forEach(b=>b.onclick=()=>{state.direction=b.dataset.direction;renderShortlist();});
  if(ranked.length){const top=ranked.slice(0,state.top),traces=['march','june'].map((d,i)=>({type:'bar',orientation:'h',y:top.map(segment),x:top.map(r=>r['premium_pct_'+d]),name:i?'June':'March',marker:{color:i?C.local:C.peer},customdata:top.map(r=>[r.neighbourhood,r.room_type,r.bedroom_segment,r.rank,r.review_score,r['priced_rows_'+d]]),hovertemplate:'%{y}<br>%{fullData.name}: %{x:+.1f}%<br>Rank %{customdata[3]} · score %{customdata[4]:.1f} pp<br>%{customdata[5]:,} priced listings<extra></extra>'}));chart('priority-bars',traces,{height:Math.max(380,top.length*47+90),barmode:'group',xaxis:{ticksuffix:'%',title:'Relative to same-date LA peer (%)',zeroline:true,zerolinecolor:'#9aaf9e'},yaxis:{autorange:'reversed',showgrid:false},margin:{l:15,r:35,t:35,b:45}},e=>{const c=e.points[0].customdata;choose({neighbourhood:c[0],room_type:c[1],bedroom_segment:c[2]});});}
  const qualified=rows.filter(r=>finite(r.premium_pct_march)&&finite(r.premium_pct_june)&&(state.direction==='Both'||r.direction===state.direction));if(!qualified.length)unavailable('persistence','No qualifying two-date evidence.');else {const traces=[];for(const status of STATUSES){const group=qualified.filter(r=>r.persistence_status===status);if(!group.length)continue;traces.push({type:'scatter',mode:'markers',x:group.map(r=>r.premium_pct_march),y:group.map(r=>r.premium_pct_june),name:status,marker:{color:statusColor[status],size:8,opacity:.7},customdata:group.map(r=>[r.neighbourhood,r.room_type,r.bedroom_segment,segment(r)]),hovertemplate:'%{customdata[3]}<br>March %{x:+.1f}% · June %{y:+.1f}%<extra>'+status+'</extra>'});}chart('persistence',traces,{height:370,xaxis:{ticksuffix:'%',title:'March premium / discount (%)',zeroline:true,zerolinecolor:'#bac7b8'},yaxis:{ticksuffix:'%',title:'June premium / discount (%)',zeroline:true,zerolinecolor:'#bac7b8'},legend:{orientation:'h',y:1.28,font:{size:9}},margin:{l:55,r:10,t:70,b:50}},e=>{const c=e.points[0].customdata;choose({neighbourhood:c[0],room_type:c[1],bedroom_segment:c[2]});});}
  const counts=STATUSES.map(s=>rows.filter(r=>r.persistence_status===s).length);chart('patterns',[{type:'bar',orientation:'h',y:STATUSES.map(s=>s.replace('Persistent ','Persistent<br>')),x:counts,marker:{color:STATUSES.map(s=>statusColor[s])},text:counts.map(num),textposition:'outside',cliponaxis:false,hovertemplate:'%{y}: %{x:,} segments<extra></extra>'}],{height:370,xaxis:{title:'Number of segments'},yaxis:{autorange:'reversed',showgrid:false},margin:{l:10,r:40,t:25,b:50}});
  function updateSelected(){const r=current;if(!r){$('selected-review').innerHTML='';return;}$('selected-review').innerHTML=`<div class="section-label">SELECTED EVIDENCE</div><h3>${esc(segment(r))}</h3><p class="quiet">${esc(r.persistence_status)} · March ${pct(r.premium_pct_march)} / June ${pct(r.premium_pct_june)}</p>${quality(r)}<div class="actions"><button class="action" id="open-selected">Open segment detail →</button><button class="action" id="export-selected">↓ Export selected evidence</button></div>${evidenceTable(r)}`;$('open-selected').onclick=()=>switchTab('detail');$('export-selected').onclick=()=>exportFile([r],'selected_review_evidence.csv');}
  updateSelected();if($('inspect'))$('inspect').onchange=e=>{if(e.target.value!=='')choose(ranked[+e.target.value]);};document.querySelectorAll('[data-segment]').forEach(tr=>tr.onclick=()=>choose(ranked[+tr.dataset.segment]));$('shortlist-export').onclick=()=>exportFile(ranked,'la_review_shortlist.csv');
}
function switchTab(tab){state.tab=tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===tab));render();}
function render(){
  if(!bundle)return;
  rows=materialize(bundle,+state.minimum,state.coverage/100,catalog.fingerprint);ranked=rank(rows,state.direction);current=rows.find(r=>r.neighbourhood===state.neighborhood&&r.room_type===state.room&&r.bedroom_segment===state.bedroom);
  $('current-segment').textContent=`${state.neighborhood} · ${state.room} · ${shortBed(state.bedroom)}`;$('filter-summary').textContent=`${catalog.stays[+state.stay]} / ${catalog.sources[+state.source]}`;$('coverage-value').textContent=state.coverage+'%';
  ({detail:renderDetail,comparison:renderComparison,shortlist:renderShortlist}[state.tab])();
}
async function load(){const id=++requestId;const key=state.stay+'-'+state.source;$('loading').hidden=false;$('error').hidden=true;
  try{if(!cache.has(key)){const res=await fetch('assets/'+catalog.bundles[key]);if(!res.ok)throw Error('The selected evidence file could not be loaded.');cache.set(key,await res.json());}if(id!==requestId)return;bundle=cache.get(key);render();}catch(e){$('error').textContent=e.message;$('error').hidden=false;}finally{if(id===requestId)$('loading').hidden=true;}
}
async function init(){try{const res=await fetch('assets/catalog.json');if(!res.ok)throw Error('Unable to load supplied evidence.');catalog=await res.json();options('neighborhood',catalog.neighborhoods);options('room',catalog.rooms);options('bedroom',BEDROOMS,BEDROOMS.map(shortBed));options('stay',catalog.stays.map((_,i)=>i),catalog.stays);options('source',catalog.sources.map((_,i)=>i),catalog.sources);sync();
  for(const key of ['snapshot','neighborhood','room','bedroom','stay','source','minimum','coverage'])$(key).addEventListener('change',e=>{if(key==='minimum'){const value=+e.target.value;if(!Number.isInteger(value)||value<1||value>10000){e.target.value=state.minimum;return;}state[key]=value;}else state[key]=e.target.value;if(['stay','source'].includes(key))load();else render();});
  $('reset').onclick=()=>{const tab=state.tab;state={...defaults,tab};sync();load();};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));await load();
}catch(e){$('loading').hidden=true;$('error').textContent=e.message;$('error').hidden=false;}}
init();
